-- Real independent sessions: observe blocked statements before completing erasure.
create extension if not exists dblink with schema extensions;
select no_plan();
create table private.c6_policy_backup as select * from private.customer_privacy_policy;
update private.customer_privacy_policy set enabled=true,revision='c6-isolated-race';
insert into auth.users(id,email,email_confirmed_at,is_anonymous)values('c6300000-0000-4000-8000-000000000001','c6-race-admin@example.invalid',now(),false),('c6300000-0000-4000-8000-000000000002','c6-race-customer@example.invalid',now(),false);
insert into public.staff_memberships(user_id,role)values('c6300000-0000-4000-8000-000000000001','admin');
update public.profiles set display_name='Before',shipping_address='{"line1":"Old private address"}' where user_id='c6300000-0000-4000-8000-000000000002';
create function public.c6_test_stale_update() returns text language plpgsql security invoker set search_path='' as $$begin update public.profiles set shipping_address='{"line1":"Old private address"}',display_name='Old name' where user_id=auth.uid();return 'wrote';exception when others then return sqlstate;end;$$;
create function public.c6_test_order() returns text language plpgsql security invoker set search_path='' as $$begin perform public.create_customer_order('{}');return 'created';exception when others then return sqlstate;end;$$;
grant execute on function public.c6_test_stale_update(),public.c6_test_order() to authenticated;
create function pg_temp.await_blocked(pids integer[]) returns boolean language plpgsql as $$declare deadline timestamptz:=clock_timestamp()+interval '10 seconds';begin loop perform pg_stat_clear_snapshot();if(select count(*) from pg_stat_activity where pid=any(pids) and wait_event_type='Lock')=cardinality(pids) then return true;end if;if clock_timestamp()>deadline then return false;end if;perform pg_sleep(0.01);end loop;end;$$;
select extensions.dblink_connect('c6_suspend','host=supabase_db_lumiq-platform dbname=postgres user=postgres password=postgres');
select extensions.dblink_connect('c6_update','host=supabase_db_lumiq-platform dbname=postgres user=postgres password=postgres');
select extensions.dblink_connect('c6_order','host=supabase_db_lumiq-platform dbname=postgres user=postgres password=postgres');
create temporary table c6_race_pids as select pid from extensions.dblink('c6_update','select pg_backend_pid()') as t(pid integer) union all select pid from extensions.dblink('c6_order','select pg_backend_pid()') as t(pid integer);
select extensions.dblink_exec('c6_suspend','begin;set role authenticated');
select extensions.dblink_exec('c6_suspend',$$set request.jwt.claims='{"sub":"c6300000-0000-4000-8000-000000000001","role":"authenticated"}'$$);
create temporary table c6_race_job as select j from extensions.dblink('c6_suspend',$$select public.request_customer_anonymization('c6300000-0000-4000-8000-000000000002','customer_request')$$) as t(j jsonb);
select extensions.dblink_exec('c6_update','set role authenticated');
select extensions.dblink_exec('c6_order','set role authenticated');
select extensions.dblink_exec('c6_update',$$set request.jwt.claims='{"sub":"c6300000-0000-4000-8000-000000000002","role":"authenticated"}'$$);
select extensions.dblink_exec('c6_order',$$set request.jwt.claims='{"sub":"c6300000-0000-4000-8000-000000000002","role":"authenticated"}'$$);
select extensions.dblink_send_query('c6_update','select public.c6_test_stale_update()');
select extensions.dblink_send_query('c6_order','select public.c6_test_order()');
select ok(pg_temp.await_blocked((select array_agg(pid) from c6_race_pids)),'old profile UPDATE and order-create actually blocked on separate sessions before suspension committed');
-- Complete erasure while both old-snapshot statements still wait. Actual Auth API is tested separately.
select extensions.dblink_exec('c6_suspend','reset role');
select extensions.dblink_exec('c6_suspend',$$update auth.users set banned_until=now()+interval '100 years',email='erased-c6300000-0000-4000-8000-000000000002@example.invalid',phone=null,raw_user_meta_data='{}',raw_app_meta_data='{}' where id='c6300000-0000-4000-8000-000000000002'$$);
create temporary table c6_race_claim as select c from extensions.dblink('c6_suspend',format('select public.claim_customer_privacy_job(%L,%L)',(select j->>'jobId' from c6_race_job),'c6300000-0000-4000-8000-000000000001')) as t(c jsonb);
select * from extensions.dblink('c6_suspend',format('select public.anonymize_customer_data(%L,%L)',(select j->>'jobId' from c6_race_job),(select c->>'leaseToken' from c6_race_claim))) as t(result jsonb);
select extensions.dblink_exec('c6_suspend','commit');
create temporary table c6_update_result as select result from extensions.dblink_get_result('c6_update') as t(result text);
create temporary table c6_order_result as select result from extensions.dblink_get_result('c6_order') as t(result text);
-- UPDATE can be filtered by EPQ or rejected by current-row guard; neither may restore PII.
select ok((select result in('42501','wrote') from c6_update_result),'stale UPDATE resolves through actual PostgreSQL authorization/recheck');
select is((select shipping_address from public.profiles where user_id='c6300000-0000-4000-8000-000000000002'),'{}'::jsonb,'blocked old-snapshot UPDATE cannot restore address after erasure');
select is((select display_name from public.profiles where user_id='c6300000-0000-4000-8000-000000000002'),'','blocked UPDATE cannot restore name');
select is((select result from c6_order_result),'42501','waiting order creation rechecks suspended profile and rejects');
select is((select count(*) from public.customer_orders where user_id='c6300000-0000-4000-8000-000000000002'),0::bigint,'no order with stale shipping can appear');
select * from extensions.dblink_get_result('c6_update') as t(result text);
select * from extensions.dblink_get_result('c6_order') as t(result text);
select is((select n from extensions.dblink('c6_update','select count(*) from public.profiles') as t(n bigint)),0::bigint,'same old JWT cannot read private profile after erase');
select extensions.dblink_disconnect('c6_suspend');select extensions.dblink_disconnect('c6_update');select extensions.dblink_disconnect('c6_order');
drop function public.c6_test_stale_update(),public.c6_test_order();
delete from public.customer_privacy_jobs where user_id='c6300000-0000-4000-8000-000000000002';
delete from auth.users where id in('c6300000-0000-4000-8000-000000000001','c6300000-0000-4000-8000-000000000002');
update private.customer_privacy_policy p set enabled=b.enabled,revision=b.revision from private.c6_policy_backup b where p.singleton=b.singleton;
drop table private.c6_policy_backup;
select * from finish();
